package org.mockito.internal.creation;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.invocation.MockitoMethod;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DelegatingMethod_equals_TriageGen2Test {

    @Test
    public void testEquals_WithSameMethod() throws NoSuchMethodException {
        // Arrange
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod1 = new DelegatingMethod(method);
        DelegatingMethod delegatingMethod2 = new DelegatingMethod(method);

        // Act & Assert
        // Note: The implementation calls method.equals(o). 
        // Since 'o' is a DelegatingMethod object and not a Method object, 
        // method.equals(o) will return false because a Method object 
        // does not equal a DelegatingMethod object.
        assertFalse(delegatingMethod1.equals(delegatingMethod2));
    }

    @Test
    public void testEquals_WithMethodObject() throws NoSuchMethodException {
        // Arrange
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method);

        // Act & Assert
        // The implementation is: return method.equals(o);
        // Here 'o' is a Method object. method.equals(method) is true.
        assertTrue(delegatingMethod.equals(method));
    }

    @Test
    public void testEquals_WithNull() throws NoSuchMethodException {
        // Arrange
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method);

        // Act & Assert
        // method.equals(null) returns false.
        assertFalse(delegatingMethod.equals(null));
    }

    @Test
    public void testEquals_WithDifferentObject() throws NoSuchMethodException {
        // Arrange
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method);
        Object differentObject = new Object();

        // Act & Assert
        // method.equals(differentObject) returns false.
        assertFalse(delegatingMethod.equals(differentObject));
    }

    @Test
    public void testEquals_WithAnotherMethodDelegatingToDifferentMethod() throws NoSuchMethodException {
        // Arrange
        Method method1 = String.class.getMethod("length");
        Method method2 = String.class.getMethod("isEmpty");
        DelegatingMethod delegatingMethod1 = new DelegatingMethod(method1);
        DelegatingMethod delegatingMethod2 = new DelegatingMethod(method2);

        // Act & Assert
        // method1.equals(delegatingMethod2) is false.
        assertFalse(delegatingMethod1.equals(delegatingMethod2));
    }
}
